export const bookGrammar: Record<string, Record<string, GrammarNote[]>> = {"a-aki":{"simplified":[{"example":"たくさん書いてありました","tip":"Used with transitive verbs to focus on the result of someone's action rather than who did it.","meaning":"Indicates a state that remains as the result of a conscious action.","pattern":"～てある / ～てあります","jlpt":"N5"},{"pattern":"～と (conditional)","tip":"Use this for natural laws, machines (pushing buttons), or fixed sequences of events.","meaning":"When A occurs, B naturally or inevitably follows.","example":"秋になると","jlpt":"N5"},{"pattern":"～そうです (hearsay)","meaning":"Indicates that the information was heard or read from another source (hearsay).","tip":"Unlike 'looks like' (sou desu), the hearsay version always follows the dictionary form (plain form).","example":"透けて見えるそうです","jlpt":"N4"},{"tip":"Using 'ni omou' often suggests an emotional reaction or a subjective perspective.","meaning":"To feel or think a certain way instinctively.","example":"可哀想に思いました","pattern":"～に思う / ～とおもう","jlpt":"N4"},{"jlpt":"N3","meaning":"While a certain state or condition continues.","tip":"Often implies that if you don't do it now, the chance will disappear (e.g., while it's still summer).","example":"夏のうちはにできています","pattern":"～うちに"},{"jlpt":"N4","pattern":"～よう (Volitional form)","example":"夏休みに海へ行こう","tip":"With Group 2 verbs (ru-verbs), replace 'ru' with 'you'. With Group 1 (u-verbs), change the 'u' sound to 'o' and add 'u'.","meaning":"The 'let's' form, used to express intent or an invitation."},{"example":"話しているのを見ると","tip":"Use 'no' instead of 'koto' when the following verb involves direct perception like seeing, hearing, or waiting.","meaning":"Normalizing a verb to turn an action into a noun/object.","pattern":"～の (Nominalizer)","jlpt":"N4"},{"jlpt":"N3","pattern":"～ようです","example":"書いたようです","tip":"It suggests a logical guess based on evidence, similar to 'it seems that' or 'it looks as if'.","meaning":"Expresses a conjecture or appearance based on what the speaker has observed."}],"intermediate":[{"example":"詩材の準備をしておくのである。","pattern":"～ておく","tip":"Focus on the preparation aspect; it means doing something now so you are ready for later.","meaning":"To do something in advance or for future use.","jlpt":"N4"},{"tip":"For verbs, change the final 'u' sound to 'e' and add 'ba'. It often expresses a logical result.","meaning":"Conditional \"if\" or \"when\".","jlpt":"N4","example":"「秋について」という注文が来れば","pattern":"～ば"},{"meaning":"It seems that... / I heard that... (indicating an inference based on evidence).","tip":"Use this when you have some basis for your guess but aren't 100% certain.","jlpt":"N4","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っているらしい。"},{"tip":"It is used to describe the degree of a state or emotion by providing an example.","meaning":"To the extent that... / So much so that...","jlpt":"N3","example":"私は胸が焼け焦げるほどに、そのみじめな女を恋した。","pattern":"～ほど"},{"pattern":"～と (conditional)","example":"耳を澄まして注意していると","jlpt":"N4","meaning":"When/if (followed by a natural or inevitable consequence).","tip":"In this context, it marks the discovery of something that happens naturally when you take an action."},{"meaning":"Despite / Although / Even though (often used at the end of a sentence to show regret or frustration).","tip":"When it ends a sentence, it often implies \"I wish it weren't so\" or \"despite the situation.\"","jlpt":"N3","pattern":"～のに","example":"もう秋が夏と一緒に忍び込んで来ているのに。"},{"pattern":"～ともなれば","example":"本職の詩人ともなれば、いつどんな注文があるかわからない。","jlpt":"N1","meaning":"When it comes to being... / If someone becomes a... (emphasizes a special status or rank).","tip":"This is used for high-level positions or significant situations where expectations naturally change."}],"original":[{"meaning":"to do something in advance for future use or to leave something in a certain state.","tip":"In speech, this often contracts: ～ておく becomes ～とく.","jlpt":"N4","pattern":"～ておく (～て置く)","example":"準備をして置くのである。"},{"meaning":"indicates a guess based on observation or information; 'it seems like' or 'apparently'.","jlpt":"N4","tip":"Unlike 'yoda', 'rashii' is used when you have some objective basis or rumors for your conclusion.","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っている言葉らしい。"},{"pattern":"～ぬ (～ず)","example":"それを見破ることが出来ぬ。","meaning":"A literary or formal negative form of a verb, equivalent to ～ない.","tip":"You will see this often in literature or proverbs. 'Surnu' becomes 'senu' and 'kuru' becomes 'konu'.","jlpt":"N3"},{"meaning":"emphasizes that once a certain high level or special status is reached, things naturally change or become serious.","tip":"Used for roles, occupations, or special occasions to show a higher standard of expectation.","jlpt":"N1","pattern":"～ともなれば / ～ともなると","example":"本職の詩人ともなれば、いつどんな注文があるか..."},{"pattern":"～ほど (～ほどに)","example":"胸が焼き焦げるほどにそのみじめな女を恋した。","meaning":"indicates the degree or extent of an action or state; 'to the extent that...'.","jlpt":"N3","tip":"Use this to add drama or emphasis to your descriptions by comparing them to an extreme limit."},{"meaning":"indicates an expectation or belief that something should be/have been a certain way, often followed by regret or surprise when it isn't.","jlpt":"N3","tip":"If followed by 'noni', it strongly implies that the reality is the opposite of the expectation.","pattern":"～はず (～筈)","example":"弱者の友であった筈なのに。"},{"meaning":"A formal/literary way to express reason or cause; 'because' or 'due to'.","tip":"This is very stiff and formal. In modern conversation, you would use 'node' or 'kara'. Shortened to 'yue' in some expressions.","jlpt":"N2","pattern":"～がゆえに (～が故に)","example":"並ハズレテ、タクマシキガ故ニ、死ナズ在リヌル。决シテ、ハカナキ態ニハ非ズ。と書かれてある。"}]},"kumo-no-ito":{"simplified":[{"jlpt":"N5","meaning":"Indicates a continuing state or an ongoing action.","pattern":"～ている/ていた","example":"白い花がたくさん咲いていて、いいにおいがしていました。","tip":"When used with verbs like 'to bloom' (saku), it describes a state rather than an active process."},{"tip":"Always use the short past (ta-form) before 'koto ga aru'.","example":"一つだけいいことをしたことがあります。","meaning":"Used to talk about past experiences (have done something before).","jlpt":"N5","pattern":"V-た + ことがある"},{"pattern":"V-volitional + とする","meaning":"To try to do or attempt an action.","jlpt":"N4","example":"踏もうとしましたが、やめました。","tip":"Often used when the attempt fails or is interrupted, like 'was about to [verb] but...'"},{"example":"生きたいと思っているはずだ","tip":"Use this when you have a logical reason to believe something must be the case.","jlpt":"N4","meaning":"Used to express a strong expectation or belief that something is true.","pattern":"～はずだ"},{"pattern":"～かもしれない","meaning":"Expresses a possibility that something might happen (might, perhaps).","jlpt":"N4","example":"極楽へ行けるかもしれない！","tip":"It's more uncertain than 'deshō'. In speech, it is often shortened to 'kamo'."},{"example":"犍陀多を地獄から助けようと思いました。","tip":"The volitional form + 'to omou' expresses a decision made in the moment or a general intention.","jlpt":"N4","meaning":"Expresses the speaker's (or subject's) intention or plan.","pattern":"V-volitional + と思う"},{"example":"とても悲しそうなかおをしました。","tip":"Drop the final 'i' or 'na' from the adjective before adding 'sō'. It means 'looks like' or 'seems'.","meaning":"Indicates that something looks a certain way based on appearance.","jlpt":"N4","pattern":"Adjective (stem) + そうな / そうに"},{"pattern":"V-volitional + と（する）","jlpt":"N3","meaning":"Describes an attempt to do something, often showing the subject's effort or struggle.","example":"自分だけ助かろうとしました。","tip":"In this context, it highlights Kandata's selfish attempt to save only himself."}],"intermediate":[{"tip":"When used with intransitive verbs like 'saku' (to bloom), it describes the current state of something.","example":"池に咲いている蓮の花は","pattern":"～ている","meaning":"Indicates an ongoing action (progressive) or a current state.","jlpt":"N5"},{"pattern":"～てやる","meaning":"To do something for someone (implied that the receiver is of lower status, a pet, or a plant).","jlpt":"N4","tip":"In polite speech, you should use 'ageru'. 'Yaru' is reserved for animals, plants, or subordinates.","example":"蜘蛛を助けてやったのです。"},{"pattern":"～かもしれない/～かもしれん","meaning":"Expresses a possibility that something might happen or be true (might, perhaps).","jlpt":"N4","tip":"It follows a plain form verb, noun, or adjective. It expresses a 50% or lower probability.","example":"地獄を抜け出せるかもしれない。"},{"jlpt":"N4","meaning":"Even if/even though. Used here as a repeated phrase to emphasize 'No matter how much I climb...'","pattern":"～ても / ～でも","example":"登っても登っても、極楽にはなかなか近づきません。","tip":"Repeating the 'verb-te mo' twice (e.g., tabe-te mo tabe-te mo) emphasizes persistence despite no change in the result."},{"example":"細い糸が切れてしまうかもしれない。","tip":"In this context, it shows the fear of an unfortunate, irreversible event (the thread snapping).","pattern":"～てしまう","jlpt":"N4","meaning":"Indicates completing an action entirely, or expressing regret/unintentionality."},{"pattern":"ご～になる (Honorific Verbs) / ご覧になる","jlpt":"N3","meaning":"The honorific form of 'miru' (to see/watch). Used to show high respect to the subject.","example":"その一部始終をご覧になっていました。","tip":"This is 'Sonkeigo'. Use it only for actions performed by someone you respect, never for yourself."},{"pattern":"～ようとする / ～ようとしている","jlpt":"N3","meaning":"To try to do or attempt to do something. Uses the volitional form.","example":"自分だけが助かろうとした犍陀多の心","tip":"It describes a point just before an action starts or an attempt to make something happen."},{"tip":"This emphasizes that an event happened so quickly that there wasn't even a moment for a secondary action.","example":"犍陀多は何かを言う間もなく、風を切って落ちていきました。","meaning":"Without even having the time to... or 'No sooner had... than...'","jlpt":"N2","pattern":"～（る）間もなく / ～暇もなく"}],"original":[{"meaning":"The polite form of the copula 'desu'. Frequently used in storytelling and formal narration.","tip":"In literature, it gives a graceful, old-fashioned, or high-status tone to the narrator.","pattern":"～でございます","jlpt":"N5","example":"ある日の事でございます。"},{"jlpt":"N4","example":"まっ白で、そのまん中にある金色の蕊からは...","meaning":"The Te-form of 'desu' (da), used to connect sentences or list qualities.","tip":"When used with nouns or Na-adjectives, it functions like 'and' to provide more information about the subject.","pattern":"～で (State-being)"},{"pattern":"～のが見える/聞こえる","tip":"Use 'no' instead of 'koto' when you are physically perceiving an action happening in real-time.","meaning":"Nominalizes a verb phrase to treat it as a noun, often used with verbs of perception like 'see' or 'hear'.","example":"蜘蛛が一匹、路ばたを這って行くのが見えました。","jlpt":"N4"},{"pattern":"～に違いない","meaning":"Expresses a strong certainty or conviction that something is true ( 'must be', 'without a doubt').","tip":"It is more subjective and based on the speaker's intuition compared to 'hazu da'.","jlpt":"N3","example":"命のあるものに違いない。"},{"example":"いくら焦って見た所で、容易に上へは出られません。","jlpt":"N2","tip":"Usually followed by a negative or pessimistic conclusion. 'Ikura' (no matter how much) is a common partner for this pattern.","meaning":"Used to say that 'even if' one does something, the result will not change or will be futile.","pattern":"～た所で (V-ta tokoro de)"},{"jlpt":"N2","example":"御釈迦様は極楽の蓮池のふちを...御歩きになっていらっしゃいました。","meaning":"The highest level of honorific speech (Sonkeigo). It uses the prefix 'o' + stem + 'ni naru' combined with 'irassharu'.","tip":"This marks the subject (Buddha) as much higher in status than the narrator or listener. 'Irassharu' is the honorific version of 'iru'.","pattern":"お～になる / いらっしゃる"},{"example":"この男を地獄から救い出してやろうと御考えになりました。","jlpt":"N4","meaning":"The volitional form + 'to omou' expresses the speaker's (or subject's) intention or plan.","tip":"Adding 'to suru' instead of 'to omou' stresses that the person is just about to start the action or is making an effort.","pattern":"～ようと思う / ～ようとする"}]},"rashomon":{"simplified":[{"tip":"Use 'no wa' for subjects and 'no o' for objects. It allows you to talk about actions as if they are things.","meaning":"Turns a verb or clause into a noun (nominalization).","example":"泥棒になるのは嫌だ","jlpt":"N5","pattern":"～のは / ～のが / ～のを"},{"tip":"Use the dictionary form for positive changes and the 'nai' form (e.g., konaku naru) for negative changes.","meaning":"Indicates a change that happens over time or reaching a certain state.","jlpt":"N4","example":"動物や泥棒が住むようになりました。","pattern":"V-dictionary form + ようになる"},{"tip":"Often translated as \"whenever\" or \"if.\" It's used for things that happen naturally, like seasonal changes or habitual actions.","pattern":"～と","example":"夕方になると、みんな怖がって門の近くに来なくなりました。","jlpt":"N4","meaning":"Natural consequence or an automatic result; 'whenever A happens, B follows.'"},{"tip":"In Japanese, the passive is often used to express a sense of being bothered or affected by someone else's action.","meaning":"Passive voice; indicates that something was done to the subject.","jlpt":"N4","example":"「もう来なくていい」と言われました。","pattern":"V-passive (～られる)"},{"tip":"Use this when you have a logical reason to believe something is true. Note that 'shika... nai' means 'only.'","pattern":"～はずだ","example":"死んだ人しかいないはずです。","jlpt":"N3","meaning":"Expectation or strong belief that something should be the case."},{"meaning":"Doing two actions at the same time.","jlpt":"N3","example":"おばあさんは震えながら言いました。","pattern":"V-stem + ながら","tip":"The second action (the verb after 'nagara') is the main focus of the sentence."},{"tip":"While 'te kuru' usually implies moving toward the speaker/present, 'te iku' implies moving away from the present toward the future.","pattern":"V-te + いく","jlpt":"N3","example":"どうやって生きていけばいいかわかりませんでした。","meaning":"Expresses a progression or change starting from now and continuing into the future."},{"tip":"Use this to show that a result occurs regardless of the condition. It's the 'even if' pattern.","pattern":"V-te + も","meaning":"Even if... (concessive conditional).","example":"俺がお前の服を盗んでも怒るなよ。","jlpt":"N2"}],"intermediate":[{"pattern":"～の（を/が）","jlpt":"N4","meaning":"Nominalizing a verb/sentence so it can function as an object.","example":"雨がやむのを待っていた。","tip":"Use 'no' instead of 'koto' when the main verb involves perception (to see/hear) or waiting."},{"jlpt":"N4","pattern":"～ようになる / ～なくなる","tip":"Connects to dictionary form for 'become' and negative form for 'stop happening'.","example":"夕方になると誰も近づかなくなった。","meaning":"Indicates a change in state or habit (to become...)."},{"pattern":"～そうだ (appearance)","jlpt":"N4","meaning":"Expressing that something looks or appears a certain way.","example":"雨宿りをする人がいそうだが。","tip":"For 'i-adjectives', drop the final 'i'. For 'ii' (good), it becomes 'yosasou'."},{"meaning":"Used for emphasis to mean 'even' or 'to the extent that'.","tip":"It implies an extreme or unexpected level that goes beyond the normal range.","example":"死体を捨てていく習慣までできた。","jlpt":"N3","pattern":"～まで"},{"meaning":"Asking for advice or expressing uncertainty about what to do.","tip":"Commonly used with question words like 'doushite' or 'doyatte' to show confusion.","example":"どうやって生きていけばいいのか分からず。","jlpt":"N4","pattern":"～ばいい（か）"},{"pattern":"～かもしれない","jlpt":"N4","example":"死人の髪を抜くのは悪いことかもしれない。","tip":"In casual speech, this is often shortened to just 'kamo'.","meaning":"Expressing a possibility or something that 'might' be true."},{"jlpt":"N3","pattern":"～（な）ければ","tip":"This is the negative conditional form. It is often used to explain a necessary action or consequence.","example":"そうしなければ飢え死にしていたからだ。","meaning":"If that were not the case (conditional negative)."},{"meaning":"A strong prohibition (Don't do...!).","example":"俺が身ぐるみ剥いでも恨むなよ。","tip":"This is very blunt and masculine. Be careful not to use it with superiors!","pattern":"Verb (Dictionary Form) + な","jlpt":"N4"}],"original":[{"meaning":"Used to turn a verb/sentence into a noun so it can be the object of a verb.","jlpt":"N5","example":"雨のふるのを眺めていた。","pattern":"Verb (Plain) + の","tip":"Unlike すること, の is often used for things you perceive with your senses, like seeing or hearing."},{"tip":"Use 見える for things that come into your line of sight naturally, and 見られる for having the opportunity to see something.","pattern":"～が見える","example":"鴉の糞が、点々と白くこびりついているのが見える。","jlpt":"N4","meaning":"Indicates that something is visible or can be seen (state), rather than the act of looking."},{"pattern":"～ている","tip":"In literature, this often sets the scene or describes the ongoing state of a character.","jlpt":"N4","meaning":"Expresses a continuous action or a current state.","example":"雨やみを待っていた。"},{"tip":"It is based on objective reasons or logical deduction. In this text, it's used with 'beki' (should) for extra emphasis on duty.","pattern":"～はずだ / ～はずである","example":"主人の家へ帰る可き筈である。","jlpt":"N3","meaning":"Expresses a strong expectation or something that is naturally supposed to be the case."},{"tip":"Determines a sense of urgency or a lack of resources (physical or temporal).","pattern":"～余裕／暇（いとま）はない","example":"手段を選んでいる遑はない。","meaning":"Indicates that there is no time, room, or margin to do something.","jlpt":"N3"},{"pattern":"～以上（は）","tip":"The second part of the sentence often contains a judgment, a duty, or a logical necessity.","meaning":"Now that; since; as long as. Expresses a strong resolve or an inevitable consequence based on a fact.","jlpt":"N2","example":"朱雀大路にある以上は、..."},{"example":"衰微の小さな余波にほかならない。","jlpt":"N2","meaning":"Nothing but; none other than. Used to emphasize a definitive reason or identity.","tip":"This is a formal expression used to assert that there is no other possible explanation.","pattern":"～にほかならない"},{"example":"考えをたどった揚句に、...","meaning":"After a long process of... (usually leading to a negative or complicated result).","jlpt":"N2","tip":"It implies that someone went through a lot of trouble or spent a long time doing something, often to reach a difficult conclusion.","pattern":"～あげく（に）"}]}};
